package com.turboio.addon;

import java.io.*;import java.nio.channels.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;

/** Account-scoped capture provenance. A source may become visible after audio
 * arrives. Only an exact conversation ID in that account establishes the link. */
final class LifelogAudioLibrary implements AutoCloseable {
 private final String account;private final File directory;private final AtomicDocument document;
 private final List<Object> sessions=new ArrayList<>();private final LifelogAudioArchive.Guard guard;
 LifelogAudioLibrary(File files,String account,LifelogAudioArchive.Guard guard)throws IOException{
  require(account!=null&&account.matches("[a-f0-9]{64}")&&guard!=null,"AUDIO_LIBRARY_ACCOUNT");this.account=account;this.guard=guard;guard.check();
  File root=files.getCanonicalFile();directory=new File(root,"lifelog-audio-library");require(root.isDirectory()&&!Files.isSymbolicLink(files.toPath()),"AUDIO_LIBRARY_PATH");if(!directory.exists())require(directory.mkdir(),"AUDIO_LIBRARY_DIRECTORY");path(directory);
  File[] entries=directory.listFiles();require(entries!=null&&entries.length<=96,"AUDIO_LIBRARY_BUDGET");for(File file:entries){require(file.getName().matches("[a-f0-9]{64}\\.json(\\.lock|\\.partial)?"),"AUDIO_LIBRARY_PATH");path(file);}
  File file=new File(directory,account+".json");for(String suffix:new String[]{"",".lock",".partial"})path(new File(file.getPath()+suffix));
  AtomicDocument opened=new AtomicDocument(file,1048576);try{Object previous=opened.read();if(previous!=null){Map<String,Object> saved=WireJson.map(previous);require(Long.valueOf(1).equals(saved.get("schema"))&&account.equals(saved.get("account")),"AUDIO_LIBRARY_ACCOUNT");List<Object> list=WireJson.list(saved.get("sessions"));require(list.size()<=256,"AUDIO_LIBRARY_BUDGET");Set<String> clocks=new HashSet<>();for(Object item:list){Map<String,Object> row=WireJson.map(item);validate(row);require(clocks.add((String)row.get("clock_epoch")),"AUDIO_LIBRARY_STATE");sessions.add(WireJson.copy(row));}}guard.check();document=opened;}catch(IOException|RuntimeException failed){opened.close();throw failed;}
 }
 static void require(boolean value,String code)throws IOException{if(!value)throw new IOException(code);}
 private static void path(File f)throws IOException{require(!Files.isSymbolicLink(f.toPath())&&f.getAbsoluteFile().equals(f.getCanonicalFile()),"AUDIO_LIBRARY_PATH");}
 static String hash(String value){try{byte[] digest=MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));StringBuilder out=new StringBuilder();for(byte b:digest){int v=b&255;out.append("0123456789abcdef".charAt(v>>>4)).append("0123456789abcdef".charAt(v&15));}return out.toString();}catch(NoSuchAlgorithmException impossible){throw new AssertionError(impossible);}}
 static String material(String account,String task){return "rayneo-lifelog-"+hash(new String(WireJson.bytes(WireJson.object("provider","rayneo-lifelog","account",account,"source_type","conversation","source_id",task)),StandardCharsets.UTF_8));}
 static long number(Map<String,Object> value,String key)throws IOException{Object n=value.get(key);require(n instanceof Number&&((Number)n).longValue()>=0,"AUDIO_LIBRARY_STATE");return ((Number)n).longValue();}
 private static void validate(Map<String,Object> r)throws IOException{
  for(String k:new String[]{"clock_epoch","peer","task_sha256","material_id","format","phase","error"})require(r.get(k) instanceof String,"AUDIO_LIBRARY_STATE");
  require(((String)r.get("clock_epoch")).matches("[a-f0-9]{32}")&&((String)r.get("peer")).matches("[a-f0-9]{64}")&&((String)r.get("task_sha256")).matches("[a-f0-9]{64}")&&((String)r.get("material_id")).matches("rayneo-lifelog-[a-f0-9]{64}")&&"opus".equals(r.get("format"))&&number(r,"rate")==16000&&number(r,"generation")>0&&number(r,"started_at")>0,"AUDIO_LIBRARY_STATE");
  number(r,"last_received_at");number(r,"saved_batches");number(r,"rejected_batches");number(r,"unconfirmed_batches");number(r,"associated_at");
  require(r.get("source_link_verified") instanceof Boolean&&Boolean.FALSE.equals(r.get("recording_complete"))&&Boolean.FALSE.equals(r.get("remote_stored"))&&Arrays.asList("RUNNING","DRAINING","STOPPED","FAILED","INTERRUPTED").contains(r.get("phase"))&&((String)r.get("error")).matches("|[A-Z_]{3,90}"),"AUDIO_LIBRARY_STATE");
 }
 private void save()throws IOException{guard.check();document.save(WireJson.object("schema",1,"account",account,"sessions",sessions));try(FileChannel dir=FileChannel.open(directory.toPath(),StandardOpenOption.READ)){dir.force(true);}guard.check();}
 void start(String clock,String peer,long generation,String task,long at)throws IOException{
  require(task!=null&&task.matches("[A-Za-z0-9_-]{1,128}")&&sessions.size()<256,"AUDIO_LIBRARY_BUDGET");for(Object raw:sessions){Map<String,Object> r=WireJson.map(raw);require(!clock.equals(r.get("clock_epoch")),"AUDIO_LIBRARY_STATE");if(Arrays.asList("RUNNING","DRAINING").contains(r.get("phase")))r.put("phase","INTERRUPTED");}
  Map<String,Object> row=WireJson.object("clock_epoch",clock,"peer",peer,"generation",generation,"task_sha256",hash(task),"material_id",material(account,task),"format","opus","rate",16000,"started_at",at,"last_received_at",at,"saved_batches",0,"rejected_batches",0,"unconfirmed_batches",0,"phase","RUNNING","error","","source_link_verified",false,"associated_at",0,"recording_complete",false,"remote_stored",false);validate(row);sessions.add(row);save();
 }
 void update(String clock,Map<String,Object> status,long at)throws IOException{for(Object raw:sessions){Map<String,Object> r=WireJson.map(raw);if(!clock.equals(r.get("clock_epoch")))continue;for(String key:new String[]{"phase","saved_batches","rejected_batches","unconfirmed_batches","error"})r.put(key,status.get(key));r.put("last_received_at",Math.max(number(r,"last_received_at"),at));validate(r);save();return;}throw new IOException("AUDIO_LIBRARY_SESSION_MISSING");}
 void recover(List<Object> archives)throws IOException{boolean changed=false;for(Object raw:sessions){Map<String,Object> session=WireJson.map(raw);long saved=0;boolean uncertain=false;for(Object item:archives){Map<String,Object> archive=WireJson.map(item),context=WireJson.map(archive.get("context"));if(!account.equals(context.get("account"))||!session.get("clock_epoch").equals(context.get("clock_epoch")))continue;if("sealed".equals(archive.get("phase")))saved+=number(archive,"count");else if("quarantined".equals(archive.get("phase")))uncertain=true;}if(saved>number(session,"saved_batches")){session.put("saved_batches",saved);changed=true;}if(Arrays.asList("RUNNING","DRAINING").contains(session.get("phase"))){session.put("phase","INTERRUPTED");session.put("error","AUDIO_CAPTURE_PROCESS_INTERRUPTED");changed=true;}if(uncertain){session.put("phase","FAILED");session.put("error","AUDIO_MANAGER_UNCERTAIN_TAIL");changed=true;}}if(changed)save();}
 void associate(Set<String> conversationIds,long at)throws IOException{guard.check();Map<String,String> known=new HashMap<>();for(String id:conversationIds)known.put(hash(id),material(account,id));boolean changed=false;for(Object raw:sessions){Map<String,Object> r=WireJson.map(raw);if(!Boolean.TRUE.equals(r.get("source_link_verified"))&&r.get("material_id").equals(known.get(r.get("task_sha256")))){r.put("source_link_verified",true);r.put("associated_at",at);changed=true;}}if(changed)save();}
 List<Object> selected(String material)throws IOException{guard.check();List<Object> found=new ArrayList<>();for(Object raw:sessions)if(material.equals(WireJson.map(raw).get("material_id")))found.add(WireJson.copy(raw));return found;}
 public void close()throws IOException{document.close();}
}
